type Support struct {
	Shop string
}

func (input *Support) String() string {
	var b strings.Builder
	length := 0
	length += 28
	length += len(input.Shop)
	length += 103
	b.Grow(length)
	b.WriteString("You are a support agent for ")
	b.WriteString(input.Shop)
	b.WriteString(". Look orders up before answering\nquestions about them. Offer a refund only for damaged or late orders.")
	return b.String()
}
